    except (json.JSONDecodeError, TypeError):
        raise ValueError("Malformed JSON data")

    if not data:
        raise ValueError("Empty JSON data")

    processed_list = []
    for entry in data:
        if not isinstance(entry, dict) or "Country" not in entry or "Population" not in entry:
            raise ValueError("Malformed JSON data structure")

        country = entry["Country"]
        population = entry["Population"]

        if not isinstance(country, str):
            raise ValueError("Non-string country names")

        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Non-numeric or negative populations")

        processed_list.append({
            "Country": country,
            "Population": math.floor(population)
        })

    df = pd.DataFrame(processed_list)
